const fs = require('fs');
const content = fs.readFileSync('/trajectory.txt', 'utf8');
const indices = [];
let idx = content.indexOf('<|');
while(idx !== -1) {
  indices.push(idx);
  idx = content.indexOf('<|', idx + 1);
}
console.log('Tag positions:', indices);
indices.forEach(pos => {
  console.log('Around pos', pos, ':', JSON.stringify(content.slice(Math.max(0, pos - 20), pos + 30)));
});
"

