const fs = require('fs');
const orig = fs.readFileSync('/trajectory.txt', 'utf8');
const trans = fs.readFileSync('/output/translation.md', 'utf8');

const origTurns = orig.split(/(?=<\|(?:user|assistant)\|>)/);
const transTurns = trans.split(/(?=<\|(?:user|assistant)\|>)/);

console.log('Orig turns:', origTurns.length);
console.log('Trans turns:', transTurns.length);

for (let i = 0; i < origTurns.length; i++) {
  console.log('=== TURN ' + i + ' ===');
  const oLines = origTurns[i].split(/\r?\n/);
  const tLines = transTurns[i].split(/\r?\n/);
  console.log('Orig lines:', oLines.length, 'Trans lines:', tLines.length);
  if (oLines.length !== tLines.length) {
    console.log('MISMATCH IN LINE COUNT!');
  }
}
"

